@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun RegisterScreen(
  patients: List<PatientItem>,
  isLoading: Boolean,
  syncViewModel: SyncViewModel,
  onPatientClick: (String) -> Unit,
  onRefresh: () -> Unit,
) {
  val isSyncing by syncViewModel.isSyncing.collectAsState()
  val syncStatus by syncViewModel.syncState.collectAsState()

  Scaffold(
    topBar = {
      TopAppBar(
        title = {
          Column {
            Text(
              "ANC Register",
              style = MaterialTheme.typography.titleLarge.copy(fontWeight = FontWeight.Bold),
            )
            if (syncStatus != null && syncStatus != "Idle") {
              Text(
                text = syncStatus ?: "",
                style = MaterialTheme.typography.labelSmall,
                color = MaterialTheme.colorScheme.onPrimaryContainer.copy(alpha = 0.8f),
              )
            }
          }
        },
        actions = {
          IconButton(
            onClick = {
              syncViewModel.syncNow { onRefresh() }
            },
            enabled = !isSyncing,
          ) {
            if (isSyncing) {
              CircularProgressIndicator(
                modifier = Modifier.size(20.dp),
                strokeWidth = 2.dp,
                color = MaterialTheme.colorScheme.primary,
              )
            } else {
              Icon(Icons.Default.Refresh, contentDescription = "Sync from server")
            }
          }
        },
        colors = TopAppBarDefaults.topAppBarColors(
          containerColor = MaterialTheme.colorScheme.primaryContainer,
          titleContentColor = MaterialTheme.colorScheme.onPrimaryContainer,
        ),
      )
    },
  ) { paddingValues ->
    Box(
      modifier = Modifier
        .fillMaxSize()
        .padding(paddingValues),
    ) {
      if (isLoading && patients.isEmpty()) {
        Box(
          modifier = Modifier.fillMaxSize(),
          contentAlignment = Alignment.Center,
        ) {
          CircularProgressIndicator()
        }
      } else if (patients.isEmpty()) {
        Box(
          modifier = Modifier
            .fillMaxSize()
            .padding(24.dp),
          contentAlignment = Alignment.Center,
        ) {
          Column(
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.Center,
          ) {
            Text(
              "No registered patients found",
              style = MaterialTheme.typography.titleMedium,
              color = MaterialTheme.colorScheme.onSurfaceVariant,
            )
            Spacer(modifier = Modifier.height(8.dp))
            Text(
              "Sync to download patients from the clinic server.",
              style = MaterialTheme.typography.bodyMedium,
              color = MaterialTheme.colorScheme.outline,
            )
            Spacer(modifier = Modifier.height(16.dp))
            Button(
              onClick = {
                syncViewModel.syncNow { onRefresh() }
              },
              enabled = !isSyncing,
            ) {
              Icon(Icons.Default.Refresh, contentDescription = null)
              Spacer(modifier = Modifier.width(8.dp))
              Text("Sync Now")
            }
          }
        }
      } else {
        LazyColumn(
          modifier = Modifier
            .fillMaxSize()
            .padding(horizontal = 16.dp, vertical = 8.dp),
          verticalArrangement = Arrangement.spacedBy(10.dp),
        ) {
          item {
            Text(
              "Currently Pregnant Patients (${patients.size})",
              style = MaterialTheme.typography.titleSmall,
              color = MaterialTheme.colorScheme.secondary,
              modifier = Modifier.padding(top = 8.dp, bottom = 4.dp),
            )
          }

          items(patients, key = { it.id }) { patient ->
            PatientCard(patient = patient, onClick = { onPatientClick(patient.id) })
          }

          item {
            Spacer(modifier = Modifier.height(16.dp))
          }
        }
      }
    }
  }
}

