@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun PatientDetailScreen(
  patientId: String,
  getPatient: suspend (String) -> PatientItem?,
  getVisits: suspend (String) -> List<VisitItem>,
  onRecordVisitClick: (String) -> Unit,
  onBackClick: () -> Unit,
) {
  var patient by remember { mutableStateOf<PatientItem?>(null) }
  var visits by remember { mutableStateOf<List<VisitItem>?>(null) }
  var isLoading by remember { mutableStateOf(true) }

  LaunchedEffect(patientId) {
    isLoading = true
    patient = getPatient(patientId)
    visits = getVisits(patientId)
    isLoading = false
  }

  Scaffold(
    topBar = {
      TopAppBar(
        title = {
          Text(
            patient?.name ?: "Patient Details",
            style = MaterialTheme.typography.titleLarge.copy(fontWeight = FontWeight.Bold),
          )
        },
        navigationIcon = {
          IconButton(onClick = onBackClick) {
            Icon(Icons.AutoMirrored.Filled.ArrowBack, contentDescription = "Back")
          }
        },
        colors = TopAppBarDefaults.topAppBarColors(
          containerColor = MaterialTheme.colorScheme.primaryContainer,
          titleContentColor = MaterialTheme.colorScheme.onPrimaryContainer,
        ),
      )
    },
    floatingActionButton = {
      ExtendedFloatingActionButton(
        onClick = { onRecordVisitClick(patientId) },
        icon = { Icon(Icons.Default.Add, contentDescription = null) },
        text = { Text("Record New Visit") },
        containerColor = MaterialTheme.colorScheme.primary,
        contentColor = MaterialTheme.colorScheme.onPrimary,
      )
    },
  ) { paddingValues ->
    Box(
      modifier = Modifier
        .fillMaxSize()
        .padding(paddingValues),
    ) {
      if (isLoading && visits == null) {
        Box(
          modifier = Modifier.fillMaxSize(),
          contentAlignment = Alignment.Center,
        ) {
          CircularProgressIndicator()
        }
      } else {
        val currentPatient = patient
        val visitList = visits.orEmpty()
        val dateFormatter = DateTimeFormatter.ofPattern("MMM dd, yyyy")

        LazyColumn(
          modifier = Modifier
            .fillMaxSize()
            .padding(horizontal = 16.dp, vertical = 12.dp),
          verticalArrangement = Arrangement.spacedBy(12.dp),
        ) {
          // Patient Header Card
          if (currentPatient != null) {
            item {
              Card(
                shape = RoundedCornerShape(16.dp),
                colors = CardDefaults.cardColors(
                  containerColor = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.5f),
                ),
                modifier = Modifier.fillMaxWidth(),
              ) {
                Column(modifier = Modifier.padding(16.dp)) {
                  Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically,
                  ) {
                    Text(
                      text = currentPatient.name,
                      style = MaterialTheme.typography.headlineSmall.copy(fontWeight = FontWeight.Bold),
                    )
                    if (currentPatient.age != null) {
                      Surface(
                        shape = RoundedCornerShape(8.dp),
                        color = MaterialTheme.colorScheme.primary.copy(alpha = 0.15f),
                      ) {
                        Text(
                          text = "${currentPatient.age} years old",
                          style = MaterialTheme.typography.labelMedium.copy(fontWeight = FontWeight.Medium),
                          modifier = Modifier.padding(horizontal = 8.dp, vertical = 4.dp),
                          color = MaterialTheme.colorScheme.primary,
                        )
                      }
                    }
                  }

                  Spacer(modifier = Modifier.height(12.dp))

                  Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                  ) {
                    Column {
                      Text(
                        "Estimated Due Date",
                        style = MaterialTheme.typography.labelMedium,
                        color = MaterialTheme.colorScheme.outline,
                      )
                      Text(
                        currentPatient.estimatedDueDate?.format(dateFormatter) ?: "Not recorded",
                        style = MaterialTheme.typography.bodyLarge.copy(fontWeight = FontWeight.SemiBold),
                        color = MaterialTheme.colorScheme.onSurface,
                      )
                    }

                    Column(horizontalAlignment = Alignment.End) {
                      Text(
                        "Current Gestational Age",
                        style = MaterialTheme.typography.labelMedium,
                        color = MaterialTheme.colorScheme.outline,
                      )
                      Text(
                        if (currentPatient.gestationalAgeWeeks != null) {
                          "${currentPatient.gestationalAgeWeeks} weeks"
                        } else {
                          "Unknown"
                        },
                        style = MaterialTheme.typography.bodyLarge.copy(fontWeight = FontWeight.SemiBold),
                        color = MaterialTheme.colorScheme.primary,
                      )
                    }
                  }
                }
              }
            }
          }

          // Past visits header
          item {
            Row(
              modifier = Modifier
                .fillMaxWidth()
                .padding(top = 8.dp, bottom = 4.dp),
              horizontalArrangement = Arrangement.SpaceBetween,
              verticalAlignment = Alignment.CenterVertically,
            ) {
              Text(
                "Past ANC Visits (${visitList.size})",
                style = MaterialTheme.typography.titleMedium.copy(fontWeight = FontWeight.Bold),
                color = MaterialTheme.colorScheme.secondary,
              )
            }
          }

          if (visitList.isEmpty()) {
            item {
              Box(
                modifier = Modifier
                  .fillMaxWidth()
                  .padding(vertical = 32.dp),
                contentAlignment = Alignment.Center,
              ) {
                Text(
                  "No past ANC visits recorded for this patient.",
                  style = MaterialTheme.typography.bodyMedium,
                  color = MaterialTheme.colorScheme.outline,
                )
              }
            }
          } else {
            items(visitList, key = { it.encounterId }) { visit ->
              VisitCard(visit = visit)
            }
          }

          item {
            // Padding for FAB
            Spacer(modifier = Modifier.height(80.dp))
          }
        }
      }
    }
  }
}

@Composable
fun VisitCard(visit: VisitItem) {
  Card(
    shape = RoundedCornerShape(12.dp),
    colors = CardDefaults.cardColors(
      containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f),
    ),
    modifier = Modifier.fillMaxWidth(),
  ) {
    Column(modifier = Modifier.padding(16.dp)) {
      Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.CenterVertically,
      ) {
        Row(verticalAlignment = Alignment.CenterVertically) {
          Icon(
            Icons.Default.Event,
            contentDescription = null,
            modifier = Modifier.size(18.dp),
            tint = MaterialTheme.colorScheme.primary,
          )
          Spacer(modifier = Modifier.width(6.dp))
          Text(
            text = "Visit: ${visit.date}",
            style = MaterialTheme.typography.titleMedium.copy(fontWeight = FontWeight.Bold),
            color = MaterialTheme.colorScheme.onSurface,
          )
        }

        if (visit.gestationalAge != null) {
          Surface(
            shape = RoundedCornerShape(6.dp),
            color = MaterialTheme.colorScheme.secondaryContainer,
          ) {
            Text(
              text = "GA: ${visit.gestationalAge}",
              style = MaterialTheme.typography.labelSmall,
              modifier = Modifier.padding(horizontal = 6.dp, vertical = 2.dp),
              color = MaterialTheme.colorScheme.onSecondaryContainer,
            )
          }
        }
      }

      Spacer(modifier = Modifier.height(10.dp))

      // Vitals grid: Weight, Blood Pressure, Hemoglobin
      Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.SpaceBetween,
      ) {
        // Weight
        Column {
          Text(
            "Weight",
            style = MaterialTheme.typography.labelSmall,
            color = MaterialTheme.colorScheme.outline,
          )
          Text(
            visit.weight ?: "Not recorded",
            style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Medium),
            color = MaterialTheme.colorScheme.onSurface,
          )
        }

        // Blood Pressure
        Column {
          Text(
            "Blood Pressure",
            style = MaterialTheme.typography.labelSmall,
            color = MaterialTheme.colorScheme.outline,
          )
          Text(
            visit.bloodPressure ?: "Not recorded",
            style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Medium),
            color = MaterialTheme.colorScheme.onSurface,
          )
        }

        // Hemoglobin (if recorded)
        Column {
          Text(
            "Hemoglobin",
            style = MaterialTheme.typography.labelSmall,
            color = MaterialTheme.colorScheme.outline,
          )
          Text(
            visit.hemoglobin ?: "—",
            style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.Medium),
            color = if (visit.hemoglobin != null) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.outline,
          )
        }
      }

      // Danger signs if any
      if (visit.dangerSigns.isNotEmpty()) {
        Spacer(modifier = Modifier.height(8.dp))
        Row(verticalAlignment = Alignment.CenterVertically) {
          Icon(
            Icons.Default.Warning,
            contentDescription = null,
            tint = MaterialTheme.colorScheme.error,
            modifier = Modifier.size(16.dp),
          )
          Spacer(modifier = Modifier.width(4.dp))
          Text(
            text = "Danger signs: ${visit.dangerSigns.joinToString(", ")}",
            style = MaterialTheme.typography.bodySmall.copy(fontWeight = FontWeight.Medium),
            color = MaterialTheme.colorScheme.error,
          )
        }
      }

      // Notes if any
      if (!visit.notes.isNullOrBlank()) {
        Spacer(modifier = Modifier.height(8.dp))
        Text(
          text = "Notes: ${visit.notes}",
          style = MaterialTheme.typography.bodySmall,
          color = MaterialTheme.colorScheme.onSurfaceVariant,
        )
      }
    }
  }
}

