import dev.ohs.fhir.datacapture.QuestionnaireConfig
import dev.ohs.fhir.model.r4.QuestionnaireResponse
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.launch

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun RecordVisitScreen(
  patientId: String,
  getQuestionnaireJson: suspend () -> String,
  onSaveVisit: suspend (String, QuestionnaireResponse) -> Unit,
  onBackClick: () -> Unit,
) {
  var questionnaireJson by remember { mutableStateOf<String?>(null) }
  var isSaving by remember { mutableStateOf(false) }
  val scope = rememberCoroutineScope()

  LaunchedEffect(Unit) {
    questionnaireJson = getQuestionnaireJson()
  }

  Scaffold(
    topBar = {
      TopAppBar(
        title = {
          Text(
            "Record ANC Visit",
            style = MaterialTheme.typography.titleLarge.copy(fontWeight = FontWeight.Bold),
          )
        },
        navigationIcon = {
          IconButton(onClick = onBackClick) {
            Icon(Icons.AutoMirrored.Filled.ArrowBack, contentDescription = "Back")
          }
        },
        colors = TopAppBarDefaults.topAppBarColors(
          containerColor = MaterialTheme.colorScheme.primaryContainer,
          titleContentColor = MaterialTheme.colorScheme.onPrimaryContainer,
        ),
      )
    },
  ) { paddingValues ->
    Box(
      modifier = Modifier
        .fillMaxSize()
        .padding(paddingValues),
    ) {
      val json = questionnaireJson
      if (json == null || isSaving) {
        Box(
          modifier = Modifier.fillMaxSize(),
          contentAlignment = Alignment.Center,
        ) {
          CircularProgressIndicator()
        }
      } else {
        Questionnaire(
          questionnaireJson = json,
          config = QuestionnaireConfig(
            showSubmitButton = true,
            showCancelButton = true,
            submitButtonText = "Save Visit",
            showRequiredText = true,
          ),
          onSubmit = { getResponse ->
            scope.launch {
              try {
                isSaving = true
                val response: QuestionnaireResponse = getResponse()
                onSaveVisit(patientId, response)
                onBackClick()
              } catch (e: CancellationException) {
                // Validation failed; form displays errors
                isSaving = false
              } catch (e: Exception) {
                isSaving = false
              }
            }
          },
          onCancel = onBackClick,
        )
      }
    }
  }
}

package com.example.ancapp.ui

import android.app.Application
import androidx.lifecycle.AndroidViewModel
import androidx.lifecycle.viewModelScope
import com.example.ancapp.data.AncRepository
import com.example.ancapp.data.PatientItem
import com.example.ancapp.data.VisitItem
import dev.ohs.fhir.model.r4.QuestionnaireResponse
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch

class AncViewModel(application: Application) : AndroidViewModel(application) {
  val repository = AncRepository(application)

  private val _patients = MutableStateFlow<List<PatientItem>>(emptyList())
  val patients = _patients.asStateFlow()

  private val _isLoading = MutableStateFlow(false)
  val isLoading = _isLoading.asStateFlow()

  init {
    loadPatients()
  }

  fun loadPatients() {
    viewModelScope.launch {
      _isLoading.value = true
      try {
        _patients.value = repository.getPatients()
      } finally {
        _isLoading.value = false
      }
    }
  }

  suspend fun getPatient(patientId: String): PatientItem? {
    return repository.getPatient(patientId)
  }

  suspend fun getPastVisits(patientId: String): List<VisitItem> {
    return repository.getPastVisits(patientId)
  }

  suspend fun getQuestionnaireJson(): String {
    return repository.getQuestionnaireJson()
  }

  suspend fun saveVisit(patientId: String, response: QuestionnaireResponse) {
    repository.saveVisit(patientId, response)
    loadPatients()
  }
}

package com.example.ancapp

import android.os.Bundle
