import com.example.ancapp.ui.RegisterScreen

class MainActivity : ComponentActivity() {
  private val ancViewModel: AncViewModel by viewModels()
  private val syncViewModel: SyncViewModel by viewModels()

  override fun onCreate(savedInstanceState: Bundle?) {
    super.onCreate(savedInstanceState)

    // Trigger initial sync on startup
    syncViewModel.syncNow {
      ancViewModel.loadPatients()
    }

    setContent {
      MaterialTheme {
        Surface(modifier = Modifier.fillMaxSize()) {
          AncAppNavHost(
            ancViewModel = ancViewModel,
            syncViewModel = syncViewModel,
          )
        }
      }
    }
  }
}

@Composable
fun AncAppNavHost(
  ancViewModel: AncViewModel,
  syncViewModel: SyncViewModel,
) {
  val navController = rememberNavController()
  val patients by ancViewModel.patients.collectAsState()
  val isLoading by ancViewModel.isLoading.collectAsState()

  NavHost(navController = navController, startDestination = "register") {
    composable("register") {
      RegisterScreen(
        patients = patients,
        isLoading = isLoading,
        syncViewModel = syncViewModel,
        onPatientClick = { patientId ->
          navController.navigate("patient_detail/$patientId")
        },
        onRefresh = {
          ancViewModel.loadPatients()
        },
      )
    }

    composable(
      route = "patient_detail/{patientId}",
      arguments = listOf(navArgument("patientId") { type = NavType.StringType }),
    ) { backStackEntry ->
      val patientId = backStackEntry.arguments?.getString("patientId") ?: ""
      PatientDetailScreen(
        patientId = patientId,
        getPatient = { ancViewModel.getPatient(it) },
        getVisits = { ancViewModel.getPastVisits(it) },
        onRecordVisitClick = { id ->
          navController.navigate("record_visit/$id")
        },
        onBackClick = {
          navController.popBackStack()
        },
      )
    }

    composable(
